from pathlib import Path
import csv,json,re
BASE=Path(__file__).resolve().parents[1]
names={x.split()[0]:x for x in json.loads((BASE/'raw/variants.json').read_text())}
sent={m.group(1):m.group(2).replace('**','') for m in re.finditer(r'^- \*\*(S[\d.-]+)\*\* (.*)$',(BASE.parent/'SENTENCES.md').read_text(),re.M)}
def q(s): return s+': «'+sent[s]+'»'
channel='B1-9.3-channel: «A channel is anything that such a command tries to leave behind: saving and running a file, registering a service, a timer or an autostart, changing a setting.»'
command='B1-9.3-command: «A command typed by a person is not considered a channel for bypassing the declaration.»'
stream='B1-9.3-stream: «A separate case: a command downloads and executes code without saving it; after a reboot, nothing that was executed must be in force.»'
law='; '.join([q('S8.3-6'),q('S8.3-8'),channel])
lawrun='; '.join([q('S8.3-6'),q('S8.3-8'),command,stream])
sources=[
('R01','Python command line','https://docs.python.org/3/using/cmdline.html','When called with a file name argument or with a file as standard input, it reads and executes a script from that file.','Execution modes: script, -c, standard input and interactive input. No installation purpose is documented for these modes.'),
('R02','Python exec','https://docs.python.org/3/library/functions.html','This function supports dynamic execution of Python code.','exec/eval consume source strings or code objects; a read file can become code.'),
('R03','Bash reference manual, maintainer copy','https://tiswww.case.edu/php/chet/bash/bashref.html','Process substitution allows a process’s input or output to be referred to using a filename.','Sections 3.5.6, 3.6, 4.1 and 9.1 document pipes/descriptors, redirections, dot/source, and history. These are shell execution functions, not installation.'),
('R04','Python modules','https://docs.python.org/3/tutorial/modules.html','Python caches the compiled version of each module in the __pycache__ directory under the name module.version.pyc','A module is source code; a compiled-only module can be loaded without its source. Directly run main scripts are not saved as bytecode by this mechanism.'),
('R05','Python interactive history','https://docs.python.org/3/tutorial/interactive.html','The default configuration also saves your history into a file named .python_history in your user directory.','The history is reused by subsequent interactive sessions; this does not establish that every history file is a valid executable script.'),
('R06','zipimport','https://docs.python.org/3/library/zipimport.html','This module adds the ability to import Python modules (*.py, *.pyc) and packages from ZIP-format archives.','Code members in an archive can execute without extracting the archive into a conventional install location.'),
('R07','Git hooks','https://git-scm.com/docs/githooks','Hooks are programs you can place in a hooks directory to trigger actions at certain points in git’s execution.','Default directory is $GIT_DIR/hooks; core.hooksPath can select another location. Executable hook files are invoked by Git.'),
('R08','Dynamic loader','https://man7.org/linux/man-pages/man8/ld.so.8.html','ld.so, ld-linux.so - dynamic linker/loader','Documents direct /lib/ld-linux.so.* invocation, LD_PRELOAD, LD_AUDIT, LD_LIBRARY_PATH and /etc/ld.so.preload. These load executable libraries; they do not install them.'),
('R09','memfd_create','https://man7.org/linux/man-pages/man2/memfd_create.2.html','However, unlike a regular file, it lives in RAM and has a volatile backing storage.','The anonymous file persists until all references are dropped; /proc/self/fd/N exposes its descriptor, not a durable file.'),
('R10','mmap','https://man7.org/linux/man-pages/man2/mmap.2.html','mmap() creates a new mapping in the virtual address space of the calling process.','MAP_ANONYMOUS and executable protection flags describe memory execution; a file-backed mapping and its backing file are different objects.'),
('R11','Debugger memory assignments','https://sourceware.org/gdb/current/onlinedocs/gdb.html/Assignment.html','To store values into arbitrary places in memory, use the','Assignments can change the debugged process at a supplied address. They do not by themselves rewrite the executable on disk.'),
('R12','Kernel binary format handlers','https://docs.kernel.org/admin-guide/binfmt-misc.html','Binfmt_misc can also recognise a filename extension aka .com or .exe.','The registration string is written to /proc/sys/fs/binfmt_misc/register; a named entry appears in that directory and selects an interpreter.'),
('R13','Browser sandbox','https://chromium.googlesource.com/chromium/src/+/main/docs/design/sandbox.md','Sandbox leverages the OS-provided security to allow code execution that cannot make persistent changes to the computer','This documents confinement intent. The variant expressly assumes confinement; helpers are separate processes and are not exempt merely because they render pages.'),
('R14','Wasmtime command line','https://docs.wasmtime.dev/cli-options.html','The run command will execute a WebAssembly module.','The documented wasmtime --dir . foo.wasm invocation grants a host directory; compilation and instantiation occur in the runtime.'),
('R15','Wasmtime filesystem security','https://docs.wasmtime.dev/security.html','applications can only access files and directories they’ve been given access to.','A preopen is a capability boundary, not evidence of its particular read/write permissions or the contents of that directory.'),
('R16','WASI context preopens','https://docs.wasmtime.dev/api/wasmtime_wasi/struct.WasiCtxBuilder.html','Configures a “preopened directory” to be available to WebAssembly.','The documented API accepts FsPerms::ReadWrite or FsPerms::ReadOnly. These have different consequences for ability to change installed executable files.'),
('R17','Socket interface','https://docs.python.org/3/library/socket.html','Bind the socket to address. The socket must not already be bound.','bind/listen create a runtime listener; getsockname reports its selected port. No persistent service registration is implied.'),
('R18','Pickle','https://docs.python.org/3/library/pickle.html','It is possible to construct malicious pickle data which will execute arbitrary code during unpickling.','The code-bearing serialized input in the variant is distinct from an ordinary non-executing data serialization.'),
('R19','Persistent binary format rules','https://www.freedesktop.org/software/systemd/man/latest/binfmt.d.html','binfmt.d — Configure additional binary formats for executables at boot','/etc/binfmt.d/*.conf is local policy; /usr/lib/binfmt.d/*.conf is the packaged counterpart. systemd-binfmt registers rules at boot.'),
('R20','dlopen','https://man7.org/linux/man-pages/man3/dlopen.3.html','The function dlopen() loads the dynamic shared object','The path names a shared library; dependencies can also be loaded. It returns a process-local handle.'),
('R21','execve','https://man7.org/linux/man-pages/man2/execve.2.html','execve() executes the program referred to by path.','The path may be an executable binary or a shebang script. The operation replaces the process image, not the named source file.'),
('R22','OSTree deployments','https://ostreedev.github.io/ostree/deployment/','A deployment is physically located at a path of the form /ostree/deploy/$stateroot/deploy/$checksum.','The deployment layer installs operating systems. Staged deployments, the repository /ostree/repo and boot entries are concrete examples of artifacts, not proof that any M row chose this backend.'),
('R23','fsync','https://man7.org/linux/man-pages/man2/fsync.2.html','fsync, fdatasync - synchronize a file\'s in-core state with storage device','File and directory persistence are separate calls; this primitive names no application-success report or declaration.'),
('R24','unlink','https://man7.org/linux/man-pages/man2/unlink.2.html','If the name was the last link to a file but any processes still have the file open','Open references can retain the inode after pathname removal. unlink does not terminate the processes using it.'),
('R25','Service manager control','https://www.freedesktop.org/software/systemd/man/latest/systemctl.html','systemctl — Control the systemd system and service manager','enable/disable manipulate links; start/stop affect runtime state. This is configuration functionality, including when invoked by a shell.'),
('R26','Service units','https://www.freedesktop.org/software/systemd/man/latest/systemd.service.html','A unit configuration file whose name ends in ".service" encodes information about a process controlled and supervised by systemd.','Restart policies and activation dependencies can recreate processes. They do not show which configuration a generic M row changes.'),
('R27','Embedded interpreter','https://docs.python.org/3/extending/embedding.html','you can pass a string containing Python statements to PyRun_SimpleString()','The embedding interface also accepts a file through PyRun_SimpleFile; embedded execution does not itself install or remove programs.'),
('R28','Descriptor execution','https://man7.org/linux/man-pages/man2/execveat.2.html','If path is an empty string and the AT_EMPTY_PATH flag is specified','A descriptor can name the executable instead of a pathname. This interface also supports the implementation of fexecve.'),
]
src={a:(b,c) for a,b,c,d,e in sources}
def cite(*ids): return ' '.join('['+i+']('+src[i][1]+')' for i in ids)
P='kind=program; Q1=no (not an unchanged installed-package member); Q2=yes, stop (S8.2-6, S8.2-9, S8.2-10, S8.2-23)'
I='kind=installed object; Q1=yes, stop (S8.2-6, S8.2-7, S8.2-8)'
S='kind=setting; Q1=no; Q2=no (values only); Q3=yes, stop (S8.2-6, S8.2-11, S8.2-12, S8.2-13, S8.2-14)'
R='kind=program record; Q1=no; Q2=no; Q3=no; Q4=program wrote non-code working state (S8.2-6, S8.2-15)'
T='kind=runtime; exists only while the computer runs, not a separate object; follows creator program/setting before Q1-Q4 (S8.2-3, S8.2-5)'
own='must be recorded by a line of its own; no package or declared derivation supplied (S8.2-1, S8.2-16)'
derived='covered by the recorded source/build line if the system itself built it from that line; otherwise own line (S8.2-16)'
parent='no separate line; covered by the line of the program/setting creating it (S8.2-5)'
general='[GENERAL] general-purpose execution without superuser rights (S8.1-8); '
rows=[]
def add(id,leaves,kind,record,route,reason,status='DECIDED',extra='',run=False):
 rows.append(dict(variant=names[id],leaves=leaves,kind=kind,record=record,route=route,law=(lawrun if run else law)+' '+extra,status=status,reason=reason))
add('C7.01','a=retained script path supplied as interpreter argument (Python manual example myscript.py); b=its running interpreter process; direct script execution need not create .pyc. '+cite('R01','R04'),'a: '+P+'; b: '+T,'a: '+own+'; b: '+parent,general+'Python documents script execution. '+cite('R01'),'Argument delivery does not exempt the saved script; a main script is not automatically a bytecode-cache producer.')
add('C7.02','a=retained executable script at the invoked path, starting #!interpreter; b=interpreter process. '+cite('R21'),'a: '+P+'; b: '+T,'a: '+own+'; b: '+parent,general+'execve and the shebang interpreter execute the file. '+cite('R21'),'The executable bit and shebang change invocation, not the question-two classification.')
add('C7.03','a=-c/-e argument string in process memory; b=process; no saved source file is intrinsic to this invocation. '+cite('R01'),'a,b: '+T+'; the personally typed command is an action, not an object (S8.2-4)','a,b: '+parent,general+'interpreter command-argument execution. '+cite('R01'),'Typed command and volatile argument storage add no independent persistent code object; any saved output is a separate channel.',run=True)
add('C7.04','a=stdin/FIFO/socket/descriptor stream and interpreter process; a named FIFO pathname may remain if separately created; here-document and process-substitution streams do not imply saved source. '+cite('R01','R03','R17'),'a: '+T+'; persistent FIFO node, if supplied, has Q1-Q3=no and Q4=program record when program-created (S8.2-15)','a: '+parent+'; program-created non-code FIFO node need not be recorded (S8.2-2, S8.2-15)',general+'shell redirects and interpreter consumes input. '+cite('R01','R03'),'Stream bytes are temporary; a saved source or policy is classified separately. Download-and-execute additionally has the explicit reboot condition.',run=True)
add('C7.05','a=retained regular source file redirected to stdin; b=/proc/self/fd/N reference and running interpreter. '+cite('R01','R28'),'a: '+P+'; b: '+T,'a: '+own+'; b: '+parent,general+'interpreter reads an existing file through stdin or descriptor. '+cite('R01','R28'),'Descriptor indirection does not turn the durable source into a temporary-only object.')
add('C7.06','a=interactive definitions in interpreter memory; b=$HOME/.python_history with the default history configuration. '+cite('R01','R05'),'a: '+T+'; b: Q1=no; Q2=unknown (actual saved history syntax/executability absent); if executable then '+P+'; otherwise Q3=no,Q4='+R,'a: '+parent+'; b: own/derived code line if executable; otherwise need not be recorded (S8.2-2, S8.2-15, S8.2-16)',general+'interactive interpreter and its history facility. '+cite('R01','R05'),'The history file is documented, but its exact contents and executability are not specified; the original typed statements remain actions.','FACT_UNKNOWN',run=True)
add('C7.07','a=recorded caller script; b=second saved file named by dot/source; c=execution state. '+cite('R03'),'a,b: '+P+' (Q1 instead wins if supplied unchanged in an installed package); c: '+T,'a: existing caller line; b: '+own+'; c: '+parent,general+'dot/source reads and executes another file in the shell. '+cite('R03'),'Recording the caller does not by itself record a separate input file it merely reads.')
add('C7.08','a=saved input path passed through open/read to exec/eval or loader; b=custom loader code file, when separate; c=code objects and process state in memory. '+cite('R02','R27'),'a,b: '+P+'; c: '+T,'a,b: '+own+'; c: '+parent,general+'dynamic evaluation/loading, with no installation/removal purpose in this mode. '+cite('R02'),'Reading the file before executing it does not make its code a program record or passive material.')
add('C7.09','a=module .py, loadable .pyc or module member in a sys.path ZIP archive; b=generated __pycache__/module.version.pyc; c=module search path value in process memory. '+cite('R04','R06','R01'),'a: '+I+' for unchanged installed-package members; otherwise '+P+'; b: '+P+'; c: '+T,'a: package line if Q1; own line for non-regenerable unpackaged code; b: '+derived+'; c: '+parent,general+'import/zipimport execute modules, not installation. '+cite('R04','R06'),'Package provenance precedes code. Regenerable bytecode can share its source line; independent bytecode needs coverage.')
add('C7.10','a=retained code file passed to embedded evaluator, or application buffer containing code; b=application/evaluator process state. The embedding API permits either file or string input. '+cite('R27'),'a saved file: '+P+'; a unsaved buffer and b: '+T,'a saved file: '+own+'; a buffer and b: '+parent,general+'application embedded evaluation, expressly distinct from any installation mode (S8.1-5). '+cite('R27'),'The code is classified by what the application executes. An editor name supplies no exemption for a saved executable input.')
add('C7.11','a=existing helper executable at the launched path; b=child process; c=saved command recipe if present. No new helper binary is created merely by launching it. '+cite('R21','R03'),'a: '+I+' if packaged unchanged; otherwise '+P+'; b: '+T+'; c: '+P,'a: existing package/program line; b: '+parent+'; c: '+own,general+'shell/exec interfaces launch the selected helper. '+cite('R21','R03'),'The child belongs to its own recorded executable, not merely to the editor or build tool that launched it.')
add('C7.12','a=$GIT_DIR/hooks/<hook-name> executable file; b=core.hooksPath value in repository configuration if changed; c=hook process. '+cite('R07'),'a: '+P+'; b: '+S+' because it selects executable hooks; c: '+T,'a: '+own+'; b: own setting line (S8.2-17); c: '+parent,general+'Git hook execution within version-control work, not an installer function. '+cite('R07'),'A project location does not exempt an executable hook or the value selecting which code is launched.')
add('C7.13','a=retained ELF program and its shared libraries; b=process image from direct /lib/ld-linux.so.* invocation. '+cite('R08'),'a: '+I+' if unchanged package content; otherwise '+P+'; b: '+T,'a: package line or own/derived program line (S8.2-16); b: '+parent,general+'dynamic linker/loader purpose. '+cite('R08'),'Direct loader invocation does not alter whether the target code is installed or requires recording.')
add('C7.14','a=retained .so files selected by LD_PRELOAD/LD_AUDIT/dlopen; b=LD_LIBRARY_PATH or other selection value in process environment; c=loaded mappings. '+cite('R08','R20'),'a: '+I+' if unchanged package member, otherwise '+P+'; b,c: '+T,'a: package or own/derived program line (S8.2-16); b,c: '+parent+'; a separately persisted loader policy is an own-line setting under S8.2-14, S8.2-17',general+'dynamic loading/FFI, not installation. '+cite('R08','R20'),'Saved libraries remain code. Volatile loader inputs are not independent settings; a saved launch/access policy would be.')
add('C7.15','a=RAM-backed memfd exposed through /proc/self/fd/N; b=process image executed by descriptor; no durable file is intrinsic. '+cite('R09','R28'),'a,b: '+T+'; a separately retained backing executable, if any, is tested Q1 then Q2','a,b: '+parent,general+'memory-file creation and descriptor execution are general execution APIs. '+cite('R09','R28'),'A volatile memory file is not an independent recorded object under the preliminary lifetime rule.',run=True)
add('C7.16','a=anonymous executable mapping and writable/executable memory aliases in the process; b=running process. A disk-backed cache is the distinct C7.18 case. '+cite('R10'),'a,b: '+T,'a,b: '+parent,general+'memory management/JIT execution APIs, not installation. '+cite('R10'),'Memory permissions do not make anonymous runtime state a separately persisted object.',run=True)
add('C7.17','a=invoked declared executable already present; b=process; c=optional shell history file selected by HISTFILE, retaining command text. '+cite('R03','R21'),'a: '+I+' if packaged, otherwise '+P+'; b: '+T+'; c: Q1=no,Q2=yes if saved content is executable shell code, otherwise Q3=no,Q4=program record (S8.2-9, S8.2-15, S8.2-23)','a: existing declaration line; b: '+parent+'; c: own/derived line if executable, otherwise need not be recorded',general+'command-shell execution explicitly covered by S8.1-8. '+cite('R03'),'The typed command is excluded; recording saved history depends on its actual executable content, which this broad variant does not specify.','FACT_UNKNOWN',run=True)
add('C7.18','a=executable generated cache, concretely __pycache__/module.version.pyc; b=its recorded source module; c=loaded code in memory. '+cite('R04'),'a: '+P+'; b: '+I+' if packaged unchanged, otherwise '+P+'; c: '+T,'a: '+derived+'; b: original package/program line; c: '+parent,general+'interpreter compiles/loads cached modules. '+cite('R04'),'Question two wins before the cache example in question four; regeneration from a recorded source supplies coverage, not a cache exemption.')
add('C7.19','a=web code/JIT in renderer memory; b=any saved web-code cache entry under the browser profile (exact backend pathname unspecified); c=recorded renderer/helper executables. '+cite('R13'),'a: '+T+'; b: Q1=no,Q2=yes code, kind=program (S8.2-9, S8.2-10), with recording exemption S8.2-21; c: '+I+' if packaged unchanged, otherwise '+P,'a: '+parent+'; b: need not be recorded under S8.2-21 because confinement is an explicit premise; c: each helper covered by its package/program line, S8.2-16, S8.2-22',general+'browser rendering/sandbox execution, not its separate extension-installer mode. '+cite('R13'),'Confinement supplies an explicit recording exception; it does not reorder the questions or exempt the separate renderer executable.')
add('C7.20','a=retained pickle file at the deserialized input path, or code-bearing macro document at its supplied path; b=evaluation state. '+cite('R18'),'a: '+P+' for the expressly code-bearing input; b: '+T,'a: '+own+'; b: '+parent,general+'deserialization/application evaluation rather than installation. '+cite('R18'),'The variant expressly executes code; its document or serialization label does not postpone question two to material.')
add('C7.21','a=foo.wasm supplied to wasmtime --dir .; b=preopened directory capability in runtime memory; c=host files possibly written within that directory. Permissions and contents of the supplied directory are not fixed. '+cite('R14','R15','R16'),'a: Q1=no,Q2=yes, kind=program (S8.2-9, S8.2-10); b: '+T+'; c: exact artifacts unknown; code would stop at Q2, chosen launch/access policy at Q3, ordinary generated data at Q4','a: own/derived line unless S8.2-21 confinement conditions hold; that capability fact is not fixed; b: '+parent+'; c: cannot decide without outputs',general+'Wasmtime documents execution, with read-only and read-write capability APIs. '+cite('R14','R16'),'A preopen alone does not establish ability to change installed code/settings. Read/write authority, reachable files and module effects are missing facts, not the former interface-wording gap.','FACT_UNKNOWN')
add('C7.22','a=modified target-process memory at the supplied address; b=injected running code; c=source injection file if supplied, at its input path. '+cite('R11','R10'),'a,b: '+T+'; c: '+P,'a,b: '+parent+'; c: '+own,'[GENERAL] unprivileged debugger manipulation; [BREAKING] only a superuser direct change past declaration to installed/settings outside built-ins (S8.1-8, S8.1-15, S8.1-16). Debugger assignments are execution/debugging functions. '+cite('R11'),'Memory changes alone are runtime objects; saved injection code is separate. Superuser status matters only when the defined breaking conditions hold.',extra=q('S8.1-16'))
add('C7.23','a=foreign binary at invoked path and its interpreter executable; b=/proc/sys/fs/binfmt_misc/<name> registration; c=/etc/binfmt.d/*.conf saved rule, if configured persistently. '+cite('R12','R19'),'a: '+I+' if packaged unchanged, otherwise '+P+' (executable through handler, so S8.2-20 does not exclude it); b: '+T+'; c: '+S,'a: package or own/derived lines (S8.2-16); b: parent handler/policy line (S8.2-5); c: own setting line; unchanged /usr/lib/binfmt.d rule is Q1 package-covered (S8.2-7, S8.2-17)','[GENERAL] unprivileged interpreter launch; [BUILTIN] systemd-binfmt configuration (S8.1-7); [BREAKING] privileged direct write past declaration to registration/policy outside built-ins (S8.1-8, S8.1-15). '+cite('R12','R19'),'Installed handlers make otherwise foreign code executable. Persistent rules and temporary registrations are different objects.',extra=q('S8.3-7'))
add('C7.24','a=recorded dispatcher file; b=instruction file at its read path or non-file instruction stream; c=effects of the custom dispatcher. No dispatcher implementation or language documentation is named in the inventory; ordinary reads alone do not establish code semantics. '+cite('R02','R27'),'a: kind=program (S8.2-9, S8.2-10); b: Q1=no; Q2 unresolved without language semantics (code => program, values => Q3/Q4); stream storage '+T+'; c: unknown','a: supplied recorded line; b: own line if executable code, own setting line if launch/access values, otherwise no required line; runtime stream follows creator; c: unknown','[UNKNOWN] documentation of the custom dispatcher purpose is absent; [GENERAL] if it is the stated unprivileged general evaluator (S8.1-8), not a documented installer/configuration tool. '+cite('R02','R27'),'No implementation or language documentation establishes the custom file format, persisted effects or installation purpose. Lack of eval/import calls alone decides none of these facts.','FACT_UNKNOWN')
add('C7.25','a=TCP listening socket and assigned local port in process/kernel memory; b=creating program; no saved network rule or service file follows from bind/listen alone. '+cite('R17'),'a: '+T+'; b: existing kind=installed object if packaged unchanged, otherwise kind=program (S8.2-7 to S8.2-10)','a: '+parent+'; b: existing package/program line. A separately saved chosen port/access policy would have its own setting line (S8.2-13, S8.2-17)',general+'application socket calls create a listener; they are not a network-configuration tool merely by opening a port. '+cite('R17'),'The explicit open-port example in S8.2-5 decides this runtime-selected port; no separate port line is required.')

# The twelve mechanics rows name obligations across all channels, not particular tool invocations.
mechanics={
'M1.01':('inactive preparation and a completion report','an installed deployment at /ostree/deploy/$stateroot/deploy/$checksum versus an uninstalled archive in a cache; a preparation log','R22'),
'M1.02':('multi-resource live activation and report','selected deployment, /etc configuration values, service-manager enablement, and runtime processes','R22','R25'),
'M2.01':('durable file generation and boot selection','deployment tree, boot entry under /boot, and a recorded success value; fsync names no report format','R22','R23'),
'M2.02':('power-cut replay of runtime and device state','durable deployment/configuration plus reconstructed processes and device settings; no specific device or replay payload is named','R22','R23','R25'),
'M3.01':('failure/timeout during preparation','candidate deployment/archive plus a failure record; their selected paths and whether a package was installed are not specified','R22'),
'M3.02':('partial activation failure or no report','partly changed configuration/files and possible surviving worker processes; a one-hour condition does not identify those objects','R25','R26'),
'M4.01':('running descendants, descriptors and mapped/injected copies','open executable inode after unlink, process mappings and children; backing-file identities and injection provenance unspecified','R24','R10'),
'M4.02':('aliases, copied executable cache/store/image and old generations','retained executable copies and /ostree/deploy/$stateroot/deploy/$checksum trees; a named removed package may or may not remain installed','R22','R24'),
'M4.03':('activators, restart policy and rules','service .service/.socket/.timer files and enabled links, Restart= value, runtime activation relation/process','R25','R26'),
'M4.04':('shared contributions of remaining declaration lines','shared package file/dependency or generated output; no actual package, line or derivation is specified','R22'),
'M5.01':('typed requirements, exact content, permissions and defaults','file content, access-mode value and package default; no selected line or object is supplied','R25','R22'),
'M5.02':('unrestricted algorithmic requirements and semantic effects','algorithm text designated as declaration and whatever files/values it generates; neither algorithm nor selected effect is supplied','R27'),
}
for id,(topic,examples,*refs) in mechanics.items():
 leaves='No specific acting tool, invocation or post-use inventory is supplied: '+topic+'. Documented object patterns, not asserted outputs: '+examples+'. '+cite(*refs)
 kind='Exact objects unknown. For any actual object: apply S8.2-5 first; Q1 installed package/unchanged member => kind=installed object (S8.2-7/8); else Q2 executable => kind=program (S8.2-9/10); else Q3 chosen whole-computer or launch/access value => kind=setting (S8.2-11 to S8.2-14); else Q4 kind=program record or kind=material by origin (S8.2-15). These are conditional rules, not observed kind counts.'
 record='Object-dependent: own/package/actual derived line under S8.2-16; own setting line or package default under S8.2-17; runtime follows creator under S8.2-5; residual records/material need not be recorded under S8.2-2. Which line is applicable is not established by this mechanics label.'
 route='[UNKNOWN] applies across C1-C10, not a single acting program. Documentation must identify installer (S8.1-4/5), other built-in (S8.1-7), general operation (S8.1-8), or privileged outside-tool bypass (S8.1-15). Examples above do not select the actor. '+cite(*refs)
 extra=q('S8.3-1')+' '+q('S8.3-4')+' '+q('S8.3-5')+' '+q('S8.1-14')+' Section 9.3 imports A.4.3: successful application must fulfill each line; removed uncovered contributions must cease being in force. No feasibility verdict is made.'
 add(id,leaves,kind,record,route,'The inventory names a cross-channel mechanics obligation, not a documented one-use operation; its actual artifacts, provenance, chosen values and acting tool are unspecified.','FACT_UNKNOWN',extra=extra)

